After creating an Pickup with an UdonBehaviour with manually synced variables the Ownership is not transferred properly and every player thinks it is owner.

Demo: https://youtu.be/jgWGGWFXslk

Used UdonSharp 0.19.6 beta and network beta SDK v4.

Update: Tested both in Unity test mode with 3 clients as well as on the open beta with a friend.

Script used:
```
using System;
using UdonSharp;
using UnityEngine;
using VRC.SDKBase;
using VRC.Udon;
[UdonBehaviourSyncMode(BehaviourSyncMode.Manual)]
public class ManualSync : UdonSharpBehaviour
{
    public float updateInterval = 0.25f;
    public float lastNetworkUpdate;
    [UdonSynced(UdonSyncMode.None)]
    public Vector3 position;
    [UdonSynced(UdonSyncMode.None)]
    public Vector3 rotation;
    public Rigidbody ownRigidbody;
    void Start()
    {
        lastNetworkUpdate = Time.unscaledTime;
        if (Networking.IsMaster)
        {
            TakeOwnership();
        }
    }
    public void LateUpdate()
    {
        if (!Networking.IsOwner(Networking.LocalPlayer, gameObject))
        {
            return;
        }
        var unscaledTime = Time.unscaledTime;
        if (unscaledTime - lastNetworkUpdate > updateInterval)
        {
            lastNetworkUpdate = unscaledTime;
            var transform1 = transform;
            position = transform1.position;
            rotation = transform1.rotation.eulerAngles;
            RequestSerialization();
        }
    }
    public override void OnPickup()
    {
        TakeOwnership();
    }
    public override void Interact()
    {
        TakeOwnership();
    }
    private void TakeOwnership()
    {
        var localPlayer = Networking.LocalPlayer;
        if (Utilities.IsValid(localPlayer))
        {
            Networking.SetOwner(localPlayer, gameObject);
        }
    }
    public override void OnOwnershipTransferred(VRCPlayerApi player)
    {
        if (!Utilities.IsValid(player))
        {
            Debug.LogWarning(GetLogPrefix() + $"ManualSync.OnOwnershipTransferred: Ownership transferred " +
                             $"to invalid player");
            return;
        }
        Debug.Log(GetLogPrefix() + $"ManualSync.OnOwnershipTransferred: Ownership transferred to " +
                  $"{player.displayName} ({player.playerId})");
    }
    public override void OnPreSerialization()
    {
        Debug.Log(GetLogPrefix() + $"ManualSync.OnPreSerialization: ");
    }
    public override void OnDeserialization()
    {
        Debug.Log(GetLogPrefix() + $"ManualSync.OnDeserialization: ");
        if (Networking.IsOwner(Networking.LocalPlayer, gameObject))
        {
            return;
        }
        if (Utilities.IsValid(ownRigidbody))
        {
            ownRigidbody.angularVelocity = Vector3.zero;
            ownRigidbody.velocity = Vector3.zero;
        }
        transform.SetPositionAndRotation(position, Quaternion.Euler(rotation));
    }
    public override void OnPostSerialization()
    {
        Debug.Log(GetLogPrefix() + $"ManualSync.OnPostSerialization: ");
    }
    public override bool OnOwnershipRequest(VRCPlayerApi requestingPlayer, VRCPlayerApi requestedOwner)
    {
        bool requester = false;
        bool requested = false;
        if (!Utilities.IsValid(requestingPlayer))
        {
            Debug.LogWarning(GetLogPrefix() + $"ManualSync.OnOwnershipRequest: requesting player is invalid");
        }
        else
        {
            Debug.Log(GetLogPrefix() + $"ManualSync.OnOwnershipRequest: " +
                      $"{requestingPlayer.displayName} ({requestingPlayer.playerId}) requests ownership change");
            requester = true;
        }

        if (!Utilities.IsValid(requestedOwner))
        {
            Debug.LogWarning(GetLogPrefix() + $"ManualSync.OnOwnershipRequest: requested owner is invalid");
        }
        else
        {
            Debug.Log(GetLogPrefix() + $"ManualSync.OnOwnershipRequest: " +
                      $"{requestedOwner.displayName} ({requestedOwner.playerId}) is requested to be owner");
            requested = true;
        }

        Debug.Log(GetLogPrefix() + $"ManualSync.OnOwnershipRequest: " +
                  $"Granting ownership transfer: {requester && requested}");
        return requester && requested;
    }
    private string GetLogPrefix()
    {
        var player = Networking.LocalPlayer;
        if (Utilities.IsValid(player))
        {
            return $"[{player.displayName} ({player.playerId})] ";
        }
        return "[Unknown local player] ";
    }
}
```

When creating a delayed custom event that continues to call itself with a new delay it will never stop when leaving e.g. the world.

I don't know if this is expected behaviour. I expected that upon destruction or disabling of the udon behaviour relevant delayed events are removed from the queue of delayed events.

Short example (U# 0.19.9/Network beta sdk v5):
```
    void Start()
    {
        SendCustomEventDelayedSeconds("Loop", Random.Range(5f, 15f), EventTiming.LateUpdate);
    }
    public void Loop()
    {
        Debug.Log("Looping with random delay");
        SendCustomEventDelayedSeconds("Loop", Random.Range(5f, 15f), EventTiming.LateUpdate);
    }
```
A solution could be to check inside *SendCustomEventDelayedSeconds* whether the udonbehaviour is active both upon enqueuing and right before execution:

```
    # could be replaced with native C# '!this.isActiveAndEnabled'
    if (!(Utilities.IsValid(this)
            && enabled
            && Utilities.IsValid(gameObject)
            && gameObject.activeInHierarchy))
    {
        // not active/updating
        return;
    }
```

